import csv


def order_totals() -> dict[str, float]:
    """See SPEC.md."""
    with open("data/rates.csv", newline="") as f:
        rates = {row["currency"]: float(row["rate_to_usd"]) for row in csv.DictReader(f)}
    totals: dict[str, float] = {}
    with open("data/orders.csv", newline="") as f:
        for row in csv.DictReader(f):
            total = float(row["quantity"]) * float(row["unit_price"]) * rates[row["currency"]]
            totals[row["order_id"]] = round(total, 2)
    return totals

